INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2, "2030/01/01 14:59:59", 3001, 1, 2.1, 0.0, 130011, "2024/10/31 12:00:00", "ヤマト", "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 3001100, -416.5, 100);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2, "2030/01/01 14:59:59", 3001, 4, 5.68, 0.0, 130011, "2024/10/31 12:00:00", "ヤマト", "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 3001101, -416.5, 101);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, "2030/01/01 14:59:59", 3001, 1, 0.0, 0.0, 130011, "2024/10/31 12:00:00", "ヤマト", "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 3001102, -416.5, 102);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, "2030/01/01 14:59:59", 3002, 1, 0.0, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 3002100, -416.5, 100);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, "2030/01/01 14:59:59", 3002, 1, 0.0, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 3002101, -416.5, 101);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2, "2030/01/01 14:59:59", 3002, 5, 8.53, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 3002102, -416.5, 102);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, "2030/01/01 14:59:59", 3002, 7, 5.67, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 3002103, -416.5, 103);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, "2030/01/01 14:59:59", 3002, 1, 0.0, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 3002104, -416.5, 104);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (3, "2030/01/01 14:59:59", 3004, 3, 0.0, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 3002300, -416.5, 300);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (7, "2030/01/01 14:59:59", 3005, 7, 0.0, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 3002400, -416.5, 301);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (1, "2030/01/01 14:59:59", 3003, 2, 4.4, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 3003200, -416.5, 200);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (7, "2030/01/01 14:59:59", 3003, 7, 0.0, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 3003201, -416.5, 201);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (2, "2030/01/01 14:59:59", 3003, 1, 5.6, 0.0, 130211, "2024/10/31 12:00:00", "フブキ", "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", 3003202, -416.5, 202);
